24	function runClaudeSync(prompt, timeoutMs = 120000) {
25	  return new Promise((resolve, reject) => {
26	    const claudePath = process.env.CLAUDE_PATH || 'claude';
27	    const childEnv = { ...process.env, HOME: os.homedir() };
28	    delete childEnv.CLAUDECODE;
29	    delete childEnv.CLAUDE_CODE_ENTRYPOINT;
30	    delete childEnv.CLAUDE_CODE_ENABLE_SDK_FILE_CHECKPOINTING;
31	    delete childEnv.CLAUDE_AGENT_SDK_VERSION;
32	    const proc = spawn(claudePath, ['-p'], { env: childEnv });
33	    let out = '', err = '';
34	    let killed = false;
35	
36	    const timer = setTimeout(() => {
37	      killed = true;
38	      proc.kill('SIGTERM');
39	      setTimeout(() => { try { proc.kill('SIGKILL'); } catch {} }, 5000);
40	    }, timeoutMs);
41	
42	    proc.stdout.on('data', d => { out += d.toString(); });
43	    proc.stderr.on('data', d => { err += d.toString(); });
44	    proc.on('close', code => {
45	      clearTimeout(timer);
46	      if (killed) reject(new Error(`Node execution timed out after ${timeoutMs / 1000}s`));
47	      else if (code !== 0) reject(new Error(err.trim() || `claude exited ${code}`));
48	      else resolve(out.trim());
49	    });
50	    proc.on('error', (e) => { clearTimeout(timer); reject(e); });
51	    proc.stdin.write(prompt, 'utf8');
52	    proc.stdin.end();
53	  });
54	}
